<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateCodeVO;

trait TemplateCodeAccessor
{
    private TemplateCodeVO $_code;
    public function getCode(): string
    {
        return $this->_code->value();
    }
    public function code(): TemplateCodeVO
    {
        return $this->_code;
    }
    public function isCodeChanged(?self $original = null): bool
    {
        return !$this->_code->equals($original?->_code);
    }
    public function withCode(TemplateCodeVO|string $code): self
    {
        $copy = clone $this;
        $copy->_code = TemplateCodeVO::from($code);
        return $copy;
    }
}
